insert into public.productos(categoria_id,codigo,nombre,descripcion,precio,orden) values
((select id from public.categorias where slug='electro'),'RP-001','ExperTea','Disfruta la armonía en cuerpo y alma con la taza perfecta de té Prepara infusiones y tés de la mejor manera: a tu gusto y con ingredientes frescos. ¡Olvídate de las bolsas de té! Aprovecha al máximo los beneficios y nutrientes de tus bebidas con la espectacular ExperTea. Con capacidad de hasta 9 tazas (2.2 L). El mango rotatorio te permite elegir la posición que te sea más cómoda, para servir con facilidad. Funcional | Su cesta de infusión se desempeña también como colador, para ahorrarte pasos ',0,1),
((select id from public.categorias where slug='electro'),'RP-002','Chocolatera','Cuando huele a chocolate, ¡huele a felicidad! Diseñada especialmente para preparar el chocolate caliente más exquisito. La Royal Prestige® Chocolatera es fabricada en acero inoxidable grado quirúrgico de la más alta calidad, con diseño estilizado terminado a mano. Su exclusivo efecto de volcán te ayuda a evitar derrames en tu cocina, para una preparación más fácil y práctica. Para el desayuno o para tomar por la tarde un rico chocolate con un delicioso queso y pan. Un producto irresistible con c',0,2),
((select id from public.categorias where slug='tapas'),'RP-003','Tapa pequeña','Las tapas del sistema de cocina de Royal Prestige® sellan la unidad para ayudar a retener el sabor y los nutrientes de tus alimentos. Diámetro: 18 cm / 7” Sirve para:',0,1),
((select id from public.categorias where slug='tapas'),'RP-004','Tapa mediana','Las tapas del sistema de cocina de Royal Prestige® sellan la unidad para ayudar a retener el sabor y los nutrientes de tus alimentos. Diámetro: 20 cm /  8" Sirve para:',0,2),
((select id from public.categorias where slug='tapas'),'RP-005','Tapa grande','Las tapas del sistema de cocina de Royal Prestige® sellan la unidad para ayudar a retener el sabor y los nutrientes de tus alimentos. Diámetro: 26 cm / 10,5" Sirve para:',0,3),
((select id from public.categorias where slug='tapas'),'RP-006','Tapa alta','Las tapas del sistema de cocina de Royal Prestige® sellan la unidad para ayudar a retener el sabor y los nutrientes de tus alimentos. Diámetro: 26 cm / 10,5" Sirve para:',0,4),
((select id from public.categorias where slug='sistemas'),'RP-007','Sistema de cocina esencial - 5 piezas','Pensando en lo fundamental que es la buena alimentación de tu familia, Royal Prestige® te presenta su Sistema de Cocina Esencial. Empezá hoy mismo a cocinar tus recetas de una forma más rápida y fácil. * Olla de 2 cuartos - Diámetro: 18 cm / 7” | Capacidad: 2 QT / 1.89 L',0,1),
((select id from public.categorias where slug='sistemas'),'RP-008','Sistema de cocina complementario - 5 piezas','Dale más elementos a tu hogar con el Sistema de Cocina Complementario y empezá a disfrutar sus beneficios. * Olla de 3 cuartos - Diámetro: 20 cm / 8” | Capacidad: 3 QT / 2.83 L * Olla de 6 cuartos - Diámetro: 26 cm / 10,5" | Capacidad: 6 QT / 5.67 L',0,2),
((select id from public.categorias where slug='sistemas'),'RP-009','Sistema de cocina clásico - 7 piezas','Disfrutá cocinando con Royal Prestige® y su Sistema de Cocina Clásico, cuyo método de cocción único y comprobado maximiza el sabor de tus recetas. * Olla de 1,5 cuartos - Diámetro: 18 cm / 7” | Capacidad: 1.5 QT / 1.41 L * Olla de 4 cuartos - Diámetro: 20 cm / 8” | Capacidad: 4 QT / 3.78 L',0,3),
((select id from public.categorias where slug='sistemas'),'RP-010','Sistema de cocina especial - 8 piezas','El Sistema Especial te brinda estilo y versatilidad superior: incluye una gran variedad de utensilios para facilitar tu tarea en la cocina e inspirar la creación de las más deliciosas recetas. * Olla de 2 cuartos - Diámetro: 18 cm / 7” | Capacidad: 2 QT / 1.89 L * Olla de 3 cuartos - Diámetro: 20 cm / 8” | Capacidad: 3 QT / 2.83 L',0,4),
((select id from public.categorias where slug='sistemas'),'RP-011','Sistema de cocina familiar - 10 piezas','Disfrutá del placer total de contar con un sistema de cocina listo para preparar cualquier clase de alimentos, sin importar lo numerosa que sea tu familia o lo sofisticadas que sean tus recetas. * Olla de 2 cuartos - Diámetro: 18 cm / 7” | Capacidad: 2 QT / 1.89 L * Olla de 4 cuartos - Diámetro: 20 cm / 8” | Capacidad: 4 QT / 3.78 L',0,5),
((select id from public.categorias where slug='sistemas'),'RP-012','Sistema de cocina profesional - 15 piezas','El sistema de cocina más completo que Royal Prestige® ofrece. Ideal para perfeccionar tu colección y complacer los gustos más variados. * Olla de 1,5 cuartos - Diámetro: 18 cm / 7” | Capacidad: 1.5 QT / 1.41 L * Olla de 2 cuartos - Diámetro: 18 cm / 7” | Capacidad: 2 QT / 1.89 L',0,6),
((select id from public.categorias where slug='ollas'),'RP-013','Olla de 1,5 cuartos - Sistema NOVEL','Hechas para ti, que buscas la más alta calidad para cocinar y alimentar mejor a tu familia Cocina sin aceite la mayoría de las carnes y aves, con muy poca o nada de agua. Tus comidas se cocinan en sus propios jugos, con nutrientes al máximo, texturas apetecibles y sabores espectaculares. Pon en práctica tus mejores recetas todos los días. Calidad superior respaldada con una garantía limitada de 50 años. Aptas para todo tipo de estufas: eléctricas, de gas o de inducción. Su diseño, construcción y',0,1),
